#[cfg(test)]
mod tests {
  use super::*;
  use std::collections::HashMap;
  use std::fs;

  impl PartialEq for Resource {
    fn eq(&self, other: &Self) -> bool {
      self.path == other.path && self.target == other.target
    }
  }

  /// Generates a random hex string used to build unique temporary directories.
  fn random_string() -> String {
    let mut buf = [0u8; 12];
    getrandom::getrandom(&mut buf).expect("failed to get random bytes");
    buf.iter().map(|b| format!("{b:02x}")).collect()
  }

  /// Files created for every test, relative to the parent of the working dir.
  const FILES: &[&str] = &[
    "scripts/index.js",
    "scripts/main.js",
    "scripts/utils/helper.js",
    "assets/logo.svg",
    "assets/fonts/font.ttf",
    "index.html",
  ];

  /// Creates a fresh temporary directory tree and returns `(root, work)`.
  ///
  /// The files live under `root` while `work` is an (initially empty) child
  /// directory used as the current working directory so that patterns can use
  /// `..` to reach the files, exercising the `_up_` normalization.
  fn setup_test_dirs() -> (PathBuf, PathBuf) {
    let root = std::env::temp_dir().join(format!("tauri-resources-test-{}", random_string()));
    let _ = fs::remove_dir_all(&root);
    for file in FILES {
      let path = root.join(file);
      fs::create_dir_all(path.parent().unwrap()).unwrap();
      fs::write(&path, b"").unwrap();
    }
    let work = root.join("work");
    fs::create_dir_all(&work).unwrap();
    (root, work)
  }

  /// Collects the targets emitted for the given patterns while running in `work`.
  fn targets(work: &Path, resources: ResourcePaths<'_>) -> Vec<PathBuf> {
    let (oks, errs) = collect(work, resources);
    assert!(errs.is_empty(), "unexpected errors: {errs:?}");
    let mut targets: Vec<PathBuf> = oks.into_iter().map(|r| r.target).collect();
    targets.sort();
    targets
  }

  /// Runs the iterator with `work` as the current dir, restoring it afterwards.
  fn collect(
    work: &Path,
    mut resources: ResourcePaths<'_>,
  ) -> (Vec<Resource>, Vec<crate::Error>) {
    let prev = std::env::current_dir().unwrap();
    std::env::set_current_dir(work).unwrap();

    let mut oks = Vec::new();
    let mut errs = Vec::new();
    for result in resources.iter() {
      match result {
        Ok(resource) => oks.push(resource),
        Err(error) => errs.push(error),
      }
    }

    std::env::set_current_dir(&prev).unwrap();
    (oks, errs)
  }

  fn sorted(mut v: Vec<PathBuf>) -> Vec<PathBuf> {
    v.sort();
    v
  }

  #[test]
  #[serial_test::serial]
  fn resource_paths_iter_slice_allow_walk() {
    let (root, work) = setup_test_dirs();

    let patterns = vec![
      "../scripts".to_string(),         // directory -> walked recursively
      "../assets/logo.svg".to_string(), // single file
      "../index.html".to_string(),
    ];

    let targets = targets(&work, ResourcePaths::new(&patterns, true));

    assert_eq!(
      targets,
      sorted(vec![
        PathBuf::from("_up_/scripts/index.js"),
        PathBuf::from("_up_/scripts/main.js"),
        PathBuf::from("_up_/scripts/utils/helper.js"),
        PathBuf::from("_up_/assets/logo.svg"),
        PathBuf::from("_up_/index.html"),
      ])
    );

    let _ = fs::remove_dir_all(&root);
  }

  #[test]
  #[serial_test::serial]
  fn resource_paths_iter_slice_no_walk() {
    let (root, work) = setup_test_dirs();

    let patterns = vec![
      "../scripts".to_string(),   // directory -> silently skipped
      "../index.html".to_string(), // single file -> kept
    ];

    let targets = targets(&work, ResourcePaths::new(&patterns, false));

    assert_eq!(targets, vec![PathBuf::from("_up_/index.html")]);

    let _ = fs::remove_dir_all(&root);
  }

  #[test]
  #[serial_test::serial]
  fn resource_paths_iter_map_allow_walk() {
    let (root, work) = setup_test_dirs();

    let mut map = HashMap::new();
    // file -> non-empty destination: destination used exactly as provided.
    map.insert("../scripts/main.js".to_string(), "js/renamed.js".to_string());
    // file -> empty destination: only the file name is used.
    map.insert("../index.html".to_string(), String::new());
    // directory -> destination: walked recursively, preserving structure.
    map.insert("../assets".to_string(), "static".to_string());
    // glob -> destination: only the matched file names are used.
    map.insert("../scripts/*.js".to_string(), "alljs".to_string());

    let targets = targets(&work, ResourcePaths::from_map(&map, true));

    assert_eq!(
      targets,
      sorted(vec![
        PathBuf::from("js/renamed.js"),
        PathBuf::from("index.html"),
        PathBuf::from("static/logo.svg"),
        PathBuf::from("static/fonts/font.ttf"),
        PathBuf::from("alljs/index.js"),
        PathBuf::from("alljs/main.js"),
      ])
    );

    // non-existent source paths are reported as `ResourcePathNotFound`.
    let mut missing = HashMap::new();
    missing.insert("../does/not/exist.txt".to_string(), "x".to_string());
    let (oks, errs) = collect(&work, ResourcePaths::from_map(&missing, true));
    assert!(oks.is_empty());
    assert_eq!(errs.len(), 1);
    assert!(matches!(errs[0], crate::Error::ResourcePathNotFound(_)));

    let _ = fs::remove_dir_all(&root);
  }

  #[test]
  #[serial_test::serial]
  fn resource_paths_iter_map_no_walk() {
    let (root, work) = setup_test_dirs();

    let mut map = HashMap::new();
    // file -> non-empty destination: destination used exactly as provided.
    map.insert("../scripts/main.js".to_string(), "js/renamed.js".to_string());
    // directory -> destination with walk disabled: silently skipped.
    map.insert("../assets".to_string(), "static".to_string());
    // glob -> destination: only the matched file names are used.
    map.insert("../scripts/*.js".to_string(), "alljs".to_string());

    let targets = targets(&work, ResourcePaths::from_map(&map, false));

    assert_eq!(
      targets,
      sorted(vec![
        PathBuf::from("js/renamed.js"),
        PathBuf::from("alljs/index.js"),
        PathBuf::from("alljs/main.js"),
      ])
    );

    let _ = fs::remove_dir_all(&root);
  }
